package com.thealgorithms.strings;

public final class HammingDistance {
    private HammingDistance() {
    }

    public static int calculateHammingDistance(String s1, String s2) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Strings must not be null");
        }

        if (s1.length() != s2.length()) {
            throw new IllegalArgumentException("String lengths must be equal");
        }

        int distance = 0;

        for (int i = 0; i < s1.length(); i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                distance++;
            }
        }
        return distance;
    }
}

package com.thealgorithms.strings;

import java.util.Arrays;

public final class LongestCommonPrefix {

    private LongestCommonPrefix() {
    }

    public static String longestCommonPrefix(String[] strs) {
        if (strs == null || strs.length == 0) {
            return "";
        }

        Arrays.sort(strs);
        String first = strs[0];
        String last = strs[strs.length - 1];

        int index = 0;
        while (index < first.length() && index < last.length() && first.charAt(index) == last.charAt(index)) {
            index++;
        }

        return first.substring(0, index);
    }
}

package com.thealgorithms.strings;

import java.util.HashMap;
import java.util.Map;

final class LongestNonRepetitiveSubstring {
    private LongestNonRepetitiveSubstring() {
    }

    public static int lengthOfLongestSubstring(String s) {
        int maxLength = 0;
        int start = 0;
        Map<Character, Integer> charIndexMap = new HashMap<>();

        for (int i = 0; i < s.length(); i++) {
            char currentChar = s.charAt(i);

            if (charIndexMap.containsKey(currentChar) && charIndexMap.get(currentChar) >= start) {

                start = charIndexMap.get(currentChar) + 1;
            }

            charIndexMap.put(currentChar, i);

            maxLength = Math.max(maxLength, i - start + 1);
        }

        return maxLength;
    }
}

